def write_fixtures(directory):
    """Materialize every fixture into *directory* and return its path.

    Subdirectories are created as needed. Contents are written as
    UTF-8 bytes so the files on disk are byte-identical to the
    recorded E1 fixture files.
    """
    root = Path(directory)
    for name, content in FIXTURES.items():
        target = root / name
        target.parent.mkdir(parents=True, exist_ok=True)
        target.write_bytes(content.encode("utf-8"))
    return root
